const _in = $input.first().json;
// Parse Claude's JSON, validate required fields, compute a confidence verdict.
let data = null;
try {
  const raw = (Array.isArray(_in.content) && _in.content[0] && _in.content[0].text) ? _in.content[0].text.trim() : '';
  data = JSON.parse(raw);
} catch (e) {
  return [{ json: { ok: false, reason: 'Claude response was not valid JSON', raw: JSON.stringify(_in).slice(0, 500) } }];
}
const REQUIRED = ['vendor_name', 'invoice_number', 'invoice_date', 'total_amount', 'currency', 'line_items', 'confidence'];
const missing = REQUIRED.filter(k => !(k in data));
if (missing.length) {
  return [{ json: { ok: false, reason: 'Missing fields: ' + missing.join(', '), ...data } }];
}
// Confidence gate: every field Claude was unsure about drags the doc to human review.
const conf = Number(data.confidence);
const needsReview = !(conf >= 0.85) || String(data.total_amount) === 'unknown' || String(data.invoice_number) === 'unknown';
const fileName = ($('Upload Invoice').first().binary?.Invoice_PDF?.fileName) || 'uploaded.pdf';
return [{ json: { ok: true, needsReview, fileName,
  vendor_name: String(data.vendor_name), invoice_number: String(data.invoice_number),
  invoice_date: String(data.invoice_date), total_amount: String(data.total_amount),
  currency: String(data.currency), line_items: JSON.stringify(data.line_items).slice(0, 1000),
  confidence: conf, notes: String(data.notes || '') } }];
